import{_ as t,o,c as d,a0 as a}from"./chunks/framework.Chtk_IOO.js";const m=JSON.parse('{"title":"Port-is-the-transport — integration by reviewable parts (2026-10-15)","description":"","frontmatter":{},"headers":[],"relativePath":"Port-Namespace-Integration-Parts.md","filePath":"Port-Namespace-Integration-Parts.md"}'),r={name:"Port-Namespace-Integration-Parts.md"};function c(n,e,i,s,h,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="port-is-the-transport-—-integration-by-reviewable-parts-2026-10-15" tabindex="-1">Port-is-the-transport — integration by reviewable parts (2026-10-15) <a class="header-anchor" href="#port-is-the-transport-—-integration-by-reviewable-parts-2026-10-15" aria-label="Permalink to &quot;Port-is-the-transport — integration by reviewable parts (2026-10-15)&quot;">​</a></h1><p>Nothing here is merged, published or deployed. The reference candidate (<code>~/.get/candidates/port-is-transport-*</code>) stays as the verified whole; this document splits it so each part can be reviewed and landed on its own.</p><p>Separation criterion: <strong>functional dependency</strong> (a later commit uses something an earlier one introduced; removing the earlier one breaks types or tests) is not the same as <strong>textual coupling</strong> (two commits edit the same lines of <code>Namespace.tsx</code> / <code>QRConnect.tsx</code>; reverting one conflicts). Only the first forces an order.</p><h2 id="part-a-—-cleaker-its-own-repository-independent-of-every-gui-part" tabindex="-1">Part A — cleaker (its own repository; independent of every GUI part) <a class="header-anchor" href="#part-a-—-cleaker-its-own-repository-independent-of-every-gui-part" aria-label="Permalink to &quot;Part A — cleaker (its own repository; independent of every GUI part)&quot;">​</a></h2><p>Branch <code>fix/port-not-in-namespace</code>, over <code>fix/normalize-surface-origin-port</code> @ <code>ee519ef</code>:</p><table tabindex="0"><thead><tr><th>commit</th><th>what</th></tr></thead><tbody><tr><td><code>c1c9c18</code></td><td>tests: a port in a namespace -- characterization (passes on base) and contract (fails where it contaminates)</td></tr><tr><td><code>4e270a7</code></td><td>port is the transport, never the namespace: constant/fqdn bare, written port reaches the transport</td></tr><tr><td><code>9587508</code></td><td>binder: an explicit door is the only door -- no fallback destination receives a signed proof</td></tr><tr><td><code>4f66f4b</code></td><td>binder: a signed proof is presented only to SELECTED destinations; fallbackOrigins is explicit (empty by default)</td></tr><tr><td><code>a03c7cc</code></td><td>binder: the namespace&#39;s own origin takes its scheme from the parser&#39;s host rule (loopback and .local: http)</td></tr><tr><td><code>d6ea6bd</code></td><td>binder: the page&#39;s location and the environment do not authorize a destination for a signature</td></tr><tr><td><code>7ab983a</code></td><td>binder: the declared origins ARE the transport; a written port is checked against them, not against a host match</td></tr><tr><td><code>d044746</code></td><td>binder: discovery and the authorization to send a signature are separate (authorizeDiscovered)</td></tr></tbody></table><p>Review as one unit; it needs nothing from the GUI. Checked against the monad: the whole suite with the base and with this cleaker gives the same 667 pass / 5 fail (0 tests change). netget depends on the PUBLISHED <code>cleaker ^3.2.1</code>: it does not see this part until a release exists and its range is moved on purpose. Behavior changes to approve: <code>fqdn</code>/<code>constant</code> carry no port (NS1, NRP4); a signature goes only to the declared transport plus the sources listed in <code>authorizeDiscovered</code> (<code>TRANSPORT_NOT_DECLARED</code> otherwise); a contradicting written port is <code>TRANSPORT_PORT_CONFLICT</code>.</p><h2 id="part-b-—-gui-the-position-label-and-the-link-model-functional-prerequisites-of-the-port-change" tabindex="-1">Part B — GUI: the position label and the link model (functional prerequisites of the port change) <a class="header-anchor" href="#part-b-—-gui-the-position-label-and-the-link-model-functional-prerequisites-of-the-port-change" aria-label="Permalink to &quot;Part B — GUI: the position label and the link model (functional prerequisites of the port change)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>commits</th><th>role</th><th>evidence</th></tr></thead><tbody><tr><td><code>226e53a5</code> <code>071bf16e</code> <code>8be67277</code> <code>b6a50ebe</code> <code>da1e8cae</code> <code>a1985c3e</code></td><td>position label chain (<code>positionExpression.ts</code>, <code>RootCheck</code>, <code>sharedRootBinding</code>, <code>confirmedLabel</code>, <code>lastAttemptFailed</code>)</td><td>later link commits <code>98dcbb8f</code> and <code>f45fc42b</code> use identifiers these introduce</td></tr><tr><td><code>98dcbb8f</code></td><td>the card&#39;s namespace follows the selected link</td><td>uses the label chain; carries the <code>hideBarItems</code> prop and <code>topBarLeftElements</code></td></tr><tr><td><code>17934e04</code> <code>95b80cb7</code></td><td><code>link.ts</code>: link, session, context, workspace as pure values</td><td>pure; <code>checkWrittenDoor</code> (port part) is appended later</td></tr><tr><td><code>8b27b0b9</code></td><td>browser integration harness (<code>demo/links.*</code>, fake monads)</td><td>test infrastructure</td></tr><tr><td><code>f45fc42b</code></td><td>one session per link; the card selects a link</td><td><code>SeedSessionProvider.tsx</code> + <code>QRConnect.tsx</code></td></tr></tbody></table><h2 id="part-c-—-gui-the-port-change-4-commits" tabindex="-1">Part C — GUI: the port change (4 commits) <a class="header-anchor" href="#part-c-—-gui-the-port-change-4-commits" aria-label="Permalink to &quot;Part C — GUI: the port change (4 commits)&quot;">​</a></h2><p><code>f7e1a807</code> tests; <code>bf37053c</code> identity vault found by namespace (conflicts asked, originals kept); <code>43c46709</code> parser mirror, typed root, <code>TRANSPORT_PORT_CONFLICT</code>, <code>chooseIdentityMechanism</code>; <code>5a35b123</code> the card says which key will be used before signing. Needs Part B (<code>f45fc42b</code>: the per-link <code>op</code> scope the vault/door code uses; <code>link.ts</code> for <code>checkWrittenDoor</code>).</p><h2 id="part-d-—-gui-interface-separable-in-intent-review-independently" tabindex="-1">Part D — GUI: interface, separable in intent (review independently) <a class="header-anchor" href="#part-d-—-gui-interface-separable-in-intent-review-independently" aria-label="Permalink to &quot;Part D — GUI: interface, separable in intent (review independently)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>commit</th><th>verdict from the evidence</th></tr></thead><tbody><tr><td><code>20c85667</code> main-server view: door and namespace on one line</td><td>reverts CLEANLY; types and unit tests unchanged — independent</td></tr><tr><td><code>e6026e34</code> identity card icons spacing</td><td>reverts cleanly — independent</td></tr><tr><td><code>8425bc77</code> <code>glyph:&lt;text&gt;</code> icon, Netget link</td><td>reverts cleanly — independent</td></tr><tr><td><code>45668a3c</code> QR declares <code>cornerRadius</code></td><td>reverting adds 2 type errors: it is a type FIX the tree needs to compile; carry it with Part B</td></tr><tr><td><code>03368bd1</code> <code>cc65ae8a</code> main-server view reads / observed state</td><td>edit <code>MainServerView.tsx</code> + <code>mainServerPresentation</code> only; no later commit of B/C uses what they introduce; revert conflicts only because later <code>main-server view</code> commits edit the same lines — review as one <code>main-server view</code> group</td></tr><tr><td><code>b5dcd6e7</code> keys/wallet icons</td><td>no later use; textual overlap with <code>e6026e34</code> and <code>Namespace.tsx</code></td></tr><tr><td><code>dd90c5ae</code> <code>3d19ee34</code> the rail QR opens the card over the page; focus returns</td><td>used only by the <code>/.me</code> page chain below; textual (<code>Namespace.tsx</code>)</td></tr><tr><td><code>6a5cf8b3</code> <code>826a29bf</code> <code>/.me</code> as a page, Welcome at <code>/</code></td><td>no use by B/C beyond <code>Namespace.tsx</code> context</td></tr><tr><td><code>7947d949</code> top bar writes the namespace at its left</td><td><code>98dcbb8f</code> edits <code>topBarLeftElements</code>: carry with Part B or re-do that hunk</td></tr><tr><td><code>d0fc83d7</code> <code>hideBarItems</code> + main-server line</td><td><code>98dcbb8f</code> uses <code>hideBarItems</code>: the prop (not the main-server hunk) is a prerequisite</td></tr></tbody></table><p>Not in the candidate and not needed: the orb icon work (99–109 of the large branch), the left-bar corner/QR control, and the QR-carries-namespace/spacing commit (<code>13152626</code>; its IPv4 parser fix is inside the port parser commit).</p><h2 id="evidence-and-its-limits" tabindex="-1">Evidence and its limits <a class="header-anchor" href="#evidence-and-its-limits" aria-label="Permalink to &quot;Evidence and its limits&quot;">​</a></h2><ul><li>Revert matrix (<code>separability.revert-matrix.tsv</code> in the from-scratch candidate): revert ONE commit from the topic head, then <code>tsc</code> and the unit suites. 3 interface commits revert cleanly; 1 is functional (types); the rest conflict textually. A revert conflict says later commits touch the same lines, not that they depend on it.</li><li>Identifier analysis: for each interface/position commit, the identifiers it introduces that a later link/port commit uses. It is a heuristic (a few hits are ordinary words); the real hits are <code>hideBarItems</code>, <code>topBarLeftElements</code>, <code>RootCheck</code>, <code>sharedRootBinding</code>, <code>confirmedLabel</code>, <code>lastAttemptFailed</code>, <code>composePosition</code>, <code>positionComposed</code>.</li><li>NOT done: building Part B and Part C as standalone stacked branches over <code>cb79c8e0</code> WITHOUT Part D. The conflicts it needs are hand resolutions in <code>Namespace.tsx</code> and <code>QRConnect.tsx</code>; that is the next piece of work and would be reviewed hunk by hunk.</li></ul><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to &quot;Order&quot;">​</a></h2><p>A (anytime, independent) → the restructure that makes <code>&lt;Me&gt;</code>/<code>&lt;Cleaker&gt;</code>/<code>QRConnect</code> exist on <code>main</code> (a separate decision) → B → C → D in any order and independently. Acceptance per part: A <code>npm test</code> of cleaker (contract 22/22); B + C <code>npm run test:runtime</code> (vault 11, parser 7, mechanism 4, contract 4, integration 32) and <code>npm run test:recorrido</code>; the real-monad path with <code>REAL_MONAD_SRC</code> set (9/9).</p>',18)])])}const b=t(r,[["render",c]]);export{m as __pageData,b as default};
